import java.io.*;
import java.util.*;

public class Educational {
    public static void main(String[] args) throws IOException {
        Educational program = new Educational();
        program.launch();
    }

    private void launch() throws IOException {
        BufferedReader stdin = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(stdin.readLine().trim().split("\\s+")[0]);
        String line = stdin.readLine();
        int[] values = Arrays.stream(stdin.readLine().trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        char[] chars = line.toCharArray();

        List<Integer> stash = new ArrayList<>();
        for (int k = 0; k < n / 2; k++) {
            if (chars[k] == chars[reflected(n, k)]) {
                if (stash.isEmpty()) {
                    stash.add(k);
                } else {
                    boolean resolved = false;
                    for (int prev : stash) {
                        if (chars[prev] != chars[k]) {
                            int p1 = values[prev] < values[reflected(n, prev)] ? prev : reflected(n, prev);
                            int p2 = values[k] < values[reflected(n, k)] ? k : reflected(n, k);
                            flip(chars, p1, p2);
                            values[p1] = 0;
                            values[p2] = 0;
                            stash.remove(Integer.valueOf(prev));
                            resolved = true;
                            break;
                        }
                    }
                    if (!resolved) stash.add(k);
                }
            }
        }

        NavigableMap<Integer, Set<Integer>> buckets = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            buckets.computeIfAbsent(values[i], k -> new HashSet<>()).add(i);
        }

        for (int k = 0; k < n / 2; k++) {
            if (chars[k] == chars[reflected(n, k)]) {
                int keyIndex = values[k] < values[reflected(n, k)] ? k : reflected(n, k);
                boolean fixed = false;
                for (Map.Entry<Integer, Set<Integer>> bucket : buckets.entrySet()) {
                    for (int alt : bucket.getValue()) {
                        if (alt == k || alt == keyIndex || chars[keyIndex] == chars[alt] || chars[keyIndex] == chars[reflected(n, alt)]) continue;
                        flip(chars, keyIndex, alt);
                        values[alt] = 0;
                        values[keyIndex] = 0;
                        buckets.get(0).add(alt);
                        buckets.get(0).add(keyIndex);
                        fixed = true;
                        break;
                    }
                    if (fixed) break;
                }
                if (chars[k] == chars[reflected(n, k)]) System.out.println("alarma");
            }
        }

        for (int k = 0; k < n / 2; k++) {
            if (chars[k] == chars[reflected(n, k)]) System.out.println("FFFF");
        }

        int total = 0;
        for (int v : values) total += v;
        System.out.println(total);
    }

    private static int reflected(int n, int i) {
        return n - i - 1;
    }

    private static void flip(char[] arr, int a, int b) {
        char temp = arr[a];
        arr[a] = arr[b];
        arr[b] = temp;
    }
}
